-- v2.3 test data, group F: 12 new live test events owned by org_a96236c5 (the test admin account),
-- generated by group-f-generate.mjs from group-f-events.json. Each row copies the structural columns of a same-type
-- template event (palette, approval, hold_minutes, country, reservation_criteria, tz, currency) and overrides all content.
-- Photos reference EXISTING event-photos storage paths (no uploads). Also renames the organizer
-- Test -> Nhà Chung. NOT a migration. Ends in ROLLBACK (dry run).
-- Rollback: supabase/rollbacks/v23_testdata_group_f_rollback.sql
BEGIN;
DO $$ DECLARE v text; BEGIN
  IF EXISTS (SELECT 1 FROM events WHERE id IN ('canhchua','bunchay','tranhtoi','dembass','saxsang','vaicu','aodaimoi','maydo','phimcu','gomxanh','giayin','chophien') OR slug IN ('canhchua','bunchay','tranhtoi','dembass','saxsang','vaicu','aodaimoi','maydo','phimcu','gomxanh','giayin','chophien')) THEN RAISE EXCEPTION 'some new keys already exist'; END IF;
  IF (SELECT name FROM organizers WHERE id = 'org_a96236c5') <> $v23$Test$v23$ THEN RAISE EXCEPTION 'organizer name changed'; END IF;
  SELECT string_agg(p, ', ') INTO v FROM unnest(ARRAY['event-photos/phokhuya/DSCF5891.jpg','event-photos/vuonsau/DSCF4212.jpg','event-photos/banrieng/DSCF4550.jpg','event-photos/bandai/opt-1791600247989-DSCF6107.jpg','event-photos/comnha/DSCF4627.jpg','event-photos/vuonsau/DSCF4880.jpg','event-photos/chieucham/DSCF4212.jpg','event-photos/jazzgac/DSCF6022.jpg','event-photos/chieucham/DSCF4880.jpg','event-photos/modular/DSCF6279.jpg','event-photos/orbit/opt-1791600255192-DSCF7202.jpg','event-photos/modular/DSCF5973.jpg','event-photos/pianomuon/DSCF4282.jpg','event-photos/jazzgac/opt-1791600280500-DSCF7039.jpg','event-photos/jazzgac/DSCF4238.jpg','event-photos/motlop/DSCF5780.jpg','event-photos/compound/DSCF5796.jpg','event-photos/motlop/DSCF5586.jpg','event-photos/orbit/DSCF4627.jpg','event-photos/orbit/opt-1791600256611-DSCF7039.jpg','event-photos/fanci/DSCF5973.jpg','event-photos/fanci/DSCF4254.jpg','event-photos/aeie/DSCF4864.jpg','event-photos/compound/DSCF7609.jpg','event-photos/vungtrang/DSCF2023.jpg','event-photos/vungtrang/opt-1791600265692-DSCF2060.jpg','event-photos/phong302/DSCF5542.jpg','event-photos/noigiay/DSCF2539.jpg','event-photos/sonmai/DSCF4517.jpg','event-photos/noigiay/DSCF4517.jpg','event-photos/noigiay/DSCF4223.jpg','event-photos/khongnguoi/DSCF6366.jpg','event-photos/phong302/DSCF2341.jpg','event-photos/compound/DSCF7597.jpg','event-photos/compound/DSCF7584.jpg','event-photos/bandai/DSCF4517.jpg']) p
   WHERE NOT EXISTS (SELECT 1 FROM event_photos ep WHERE ep.storage_path = p);
  IF v IS NOT NULL THEN RAISE EXCEPTION 'unknown photo paths: %', v; END IF;
END $$;
UPDATE organizers SET name = $v23$Nhà Chung$v23$ WHERE id = 'org_a96236c5';
INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"canhchua","key":"canhchua","slug":"canhchua","organizer_id":"org_a96236c5","name":"Canh Chua Chủ Nhật","category":"Supper club","cat_key":"supper","cat_label":"Supper club","description":"Một bữa cơm miền Tây trong căn nhà phố ở Phú Nhuận. Nồi canh chua cá lóc nấu với bạc hà, đậu bắp và me chua, ăn cùng cá kho tộ và rau luộc chấm kho quẹt. Bàn tròn, ăn chung, xới cơm cho nhau. Chủ nhà kể chuyện quê ở Cần Thơ trong lúc mọi người ăn. Cơm thêm thoải mái.","intro":"Bữa cơm miền Tây quanh một nồi canh chua.\n\nBàn tròn, ăn chung, cá kho tộ và rau luộc chấm kho quẹt.","included":"Canh chua cá ▪︎ 3 món mặn ▪︎ trà đá","included_items":[{"label":"Canh chua cá","detail":"nấu trong nồi đất, ăn chung"},{"label":"3 món mặn","detail":"cá kho, rau luộc, trứng chiên"},{"label":"trà đá","detail":"rót thêm thoải mái"}],"area":"Phú Nhuận","neighborhood":"Khu phố 7","lat":10.799312,"lng":106.680244,"price_vnd":450000,"price_cents":45000000,"capacity":8,"seats_remaining":8,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/phokhuya/DSCF5891.jpg","cover_r2_ref":null,"keywords":["Canh","Chua","Chủ","Nhật","Phú Nhuận","Supper club","Canh chua cá","3 món mặn","trà đá"],"chat_greeting":"Chào bạn! Có món nào bạn không ăn được thì nhắn mình trước nhé.","chat_greeting_en":"Hi! Tell me before the night if there is anything you can't eat.","details":{"v":1,"alcohol":"none","min_age":"16","dietary":["pescatarian","can_accommodate"],"dietary_note":"Có bản chay cho nồi canh","dress_code":"Thoải mái"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
  'event_date', (now() AT TIME ZONE t.tz)::date + 12, 'event_time', '19:00'::time,
  'starts_at', (((now() AT TIME ZONE t.tz)::date + 12) + '19:00'::time) AT TIME ZONE t.tz,
