INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"bunchay","key":"bunchay","slug":"bunchay","organizer_id":"org_a96236c5","name":"Bữa Chay Sân Gạch","category":"Supper club","cat_key":"supper","cat_label":"Supper club","description":"Bữa tối thuần chay trên sân gạch của một căn nhà cũ ở Quận 10. Năm món nấu từ rau chợ sáng, đậu hũ tự làm và nấm rơm, không có món giả thịt. Nước rau má hoặc sâm bí đao, tráng miệng là chè đậu theo mùa. Phù hợp cả với người chưa từng ăn chay cả bữa. Ăn xong ai muốn thì ở lại rửa chén cùng.","intro":"Một bữa tối thuần chay, không món giả thịt.\n\nRau chợ sáng, đậu hũ tự làm, trên một sân gạch cũ.","included":"5 món chay ▪︎ nước mát ▪︎ tráng miệng","included_items":[{"label":"5 món chay","detail":"theo rau chợ sáng"},{"label":"nước mát","detail":"rau má hoặc sâm bí đao"},{"label":"tráng miệng","detail":"chè đậu theo mùa"}],"area":"Quận 10","neighborhood":"Khu phố 4","lat":10.773418,"lng":106.667932,"price_vnd":380000,"price_cents":38000000,"capacity":10,"seats_remaining":10,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/bandai/opt-1791600247989-DSCF6107.jpg","cover_r2_ref":null,"keywords":["Bữa","Chay","Sân","Gạch","Quận 10","Supper club","5 món chay","nước mát","tráng miệng"],"chat_greeting":"Chào bạn! Bữa này thuần chay. Có câu hỏi gì cứ nhắn mình.","chat_greeting_en":"Hi! The whole menu is vegan. Ask me anything.","details":{"v":1,"alcohol":"none","min_age":"16","dietary":["vegetarian","vegan"],"dietary_note":"Toàn bộ thực đơn thuần chay","dress_code":"Thoải mái"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
