INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"dembass","key":"dembass","slug":"dembass","organizer_id":"org_a96236c5","name":"Đêm Bass","category":"Nhạc","cat_key":"music","cat_label":"Nhạc","description":"Một đêm bass nặng trong nhà kho cũ ở Quận 4. Kép mở màn với dub chậm, Mưa Nhân Tạo đánh tới khuya với hệ thống loa dựng riêng cho buổi này. Phòng đứng, đèn đỏ, không chụp ảnh có flash. Earplugs miễn phí ở cửa, quầy bia mở tới khi tắt nhạc. Mang theo áo khoác mỏng vì quạt thổi mạnh gần loa.","intro":"Bass nặng trong một nhà kho ở Quận 4.\n\nHai nghệ sĩ, một hệ thống loa dựng riêng, đèn đỏ tới khuya.","included":"Vào cửa ▪︎ earplugs","included_items":[{"label":"Vào cửa","detail":"vào và ra tự do"},{"label":"earplugs","detail":"lấy ở bàn soát vé"}],"area":"Quận 4","neighborhood":"Khu phố 1","lat":10.757216,"lng":106.704884,"price_vnd":250000,"price_cents":25000000,"capacity":60,"seats_remaining":60,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/modular/DSCF6279.jpg","cover_r2_ref":null,"keywords":["Đêm","Bass","Quận 4","Nhạc","Vào cửa","earplugs"],"chat_greeting":"Chào bạn! Có câu hỏi về đêm này cứ nhắn mình.","chat_greeting_en":"Hi! Got a question about the night? Just ask.","details":{"v":1,"alcohol":"paid","min_age":"18","lineup":["Kép","Mưa Nhân Tạo"],"genre":["electronic"],"format":"standing","alcohol_note":"Bia và cocktail bán tại quầy"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
