INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"saxsang","key":"saxsang","slug":"saxsang","organizer_id":"org_a96236c5","name":"Sax Buổi Sáng","category":"Nhạc","cat_key":"music","cat_label":"Nhạc","description":"Jazz buổi sáng trong khu vườn của một quán cà phê ở Thảo Điền. Linh Sax chơi cùng bộ ba Gác những bản standard chậm, hợp với ly cà phê phin đầu ngày. Ghế mây dưới tán cây, trẻ em đi cùng được. Một ly cà phê đã gồm trong vé. Đến sớm để có ghế gần sân khấu, chó mèo không vào được vườn.","intro":"Jazz chậm và cà phê phin trong một khu vườn buổi sáng.\n\nGhế mây dưới tán cây, trẻ em đi cùng được.","included":"Vào cửa ▪︎ cà phê","included_items":[{"label":"Vào cửa","detail":"một chỗ ngồi trong vườn"},{"label":"cà phê","detail":"một ly cà phê phin"}],"area":"Thảo Điền","neighborhood":"Khu phố 2","lat":10.803116,"lng":106.735408,"price_vnd":150000,"price_cents":15000000,"capacity":25,"seats_remaining":25,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/pianomuon/DSCF4282.jpg","cover_r2_ref":null,"keywords":["Sax","Buổi","Sáng","Thảo Điền","Nhạc","Vào cửa","cà phê"],"chat_greeting":"Chào bạn! Sáng hôm đó gặp nhau trong vườn nhé.","chat_greeting_en":"Hi! See you in the garden that morning.","details":{"v":1,"alcohol":"none","min_age":"16","lineup":["Linh Sax","Bộ ba Gác"],"genre":["jazz"],"format":"seated"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
