INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"aodaimoi","key":"aodaimoi","slug":"aodaimoi","organizer_id":"org_a96236c5","name":"Áo Dài Mới: Lookbook","category":"Thời trang","cat_key":"fashion","cat_label":"Thời trang","description":"Nhà Lụa và Tơ Sen ra mắt mười hai mẫu áo dài mới trong một biệt thự cũ ở Quận 1. Áo dài cắt gọn, vải lụa tơ tằm nhuộm tay, mặc được cả ngày thường. Show ba mươi phút trên cầu thang gỗ, sau đó các mẫu được treo lại để xem gần và đặt may theo số đo. Ăn mặc tự do.","intro":"Mười hai mẫu áo dài mới, trình diễn trên cầu thang gỗ của một biệt thự cũ.\n\nXem gần sau show, đặt may theo số đo.","included":"Show 30 phút ▪︎ một ly vang ▪︎ lookbook in","included_items":[{"label":"Show 30 phút","detail":"mười hai mẫu áo dài mới"},{"label":"một ly vang","detail":"rót khi vào cửa"},{"label":"lookbook in","detail":"bản in giới hạn"}],"area":"Quận 1","neighborhood":"Khu phố 4","lat":10.779432,"lng":106.702116,"price_vnd":350000,"price_cents":35000000,"capacity":24,"seats_remaining":24,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/orbit/DSCF4627.jpg","cover_r2_ref":null,"keywords":["Áo","Dài","Mới","Lookbook","Quận 1","Thời trang","Show 30 phút","một ly vang","lookbook in"],"chat_greeting":"Chào bạn! Muốn đặt may sau show thì nhắn mình để giữ lịch đo.","chat_greeting_en":"Hi! Message me if you want a fitting slot after the show.","details":{"v":1,"alcohol":"included","min_age":"18","brands":["Nhà Lụa","Tơ Sen"],"experience":"show","price_range":"premium","alcohol_note":"Một ly vang khi vào cửa"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
