INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"maydo","key":"maydo","slug":"maydo","organizer_id":"org_a96236c5","name":"Một Buổi May Đo","category":"Thời trang","cat_key":"fashion","cat_label":"Thời trang","description":"Một buổi chiều ở Xưởng Kim Chỉ, Bình Thạnh. Thợ may chính đo cho bạn từng số, cùng bạn chọn vải từ kệ lanh và cotton, rồi vẽ dáng áo lên giấy. Vé gồm một chiếc sơ mi may đo, hoàn thành trong hai tuần và giao tận nơi. Nhóm nhỏ để ai cũng được đo kỹ. Mang theo một chiếc áo bạn thích.","intro":"Một buổi đo may với thợ chính, về với một chiếc sơ mi của riêng bạn.\n\nChọn vải, vẽ dáng, hai tuần sau nhận áo.","included":"Đo và chọn vải ▪︎ một áo sơ mi ▪︎ trà","included_items":[{"label":"Đo và chọn vải","detail":"với thợ may chính"},{"label":"một áo sơ mi","detail":"may xong trong hai tuần"},{"label":"trà","detail":"trà nóng suốt buổi"}],"area":"Bình Thạnh","neighborhood":"Khu phố 12","lat":10.802884,"lng":106.709516,"price_vnd":650000,"price_cents":65000000,"capacity":6,"seats_remaining":6,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/fanci/DSCF4254.jpg","cover_r2_ref":null,"keywords":["Một","Buổi","May","Đo","Bình Thạnh","Thời trang","Đo và chọn vải","một áo sơ mi","trà"],"chat_greeting":"Chào bạn! Mặc một chiếc áo bạn thích nhất để thợ tham khảo dáng nhé.","chat_greeting_en":"Hi! Wear your favourite shirt so we can use it as a reference.","details":{"v":1,"alcohol":"none","min_age":"16","brands":["Xưởng Kim Chỉ"],"experience":"fitting","price_range":"mid"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
