INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"phimcu","key":"phimcu","slug":"phimcu","organizer_id":"org_a96236c5","name":"Phim Cũ, Ảnh Mới","category":"Phòng tranh","cat_key":"gallery","cat_label":"Phòng tranh","description":"Kha Nguyên tìm thấy hai mươi cuộn phim chưa tráng trong một tiệm ảnh đóng cửa ở Chợ Lớn. Anh tráng chúng sau ba mươi năm và treo cạnh những tấm anh tự chụp lại đúng chỗ đó hôm nay. Triển lãm nhỏ trong một tiệm ảnh cũ, bàn rọi phim vẫn còn dùng được. Ảnh in được bán sau buổi.","intro":"Hai mươi cuộn phim bị bỏ quên, tráng sau ba mươi năm.\n\nMỗi tấm cũ treo cạnh một tấm chụp lại đúng chỗ đó hôm nay.","included":"Vào cửa ▪︎ bưu thiếp","included_items":[{"label":"Vào cửa","detail":"xem không giới hạn thời gian"},{"label":"bưu thiếp","detail":"một tấm in từ triển lãm"}],"area":"Quận 5","neighborhood":"Khu phố 3","lat":10.754812,"lng":106.666704,"price_vnd":90000,"price_cents":9000000,"capacity":30,"seats_remaining":30,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/vungtrang/DSCF2023.jpg","cover_r2_ref":null,"keywords":["Phim","Cũ","Ảnh","Mới","Quận 5","Phòng tranh","Vào cửa","bưu thiếp"],"chat_greeting":"Chào bạn! Kha có mặt cả buổi để kể chuyện từng cuộn phim.","chat_greeting_en":"Hi! Kha will be there all evening to talk about each roll.","details":{"v":1,"alcohol":"none","min_age":"16","artists":["Kha Nguyên"],"medium":["photography"]},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
