INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"gomxanh","key":"gomxanh","slug":"gomxanh","organizer_id":"org_a96236c5","name":"Gốm Xanh Biên Hoà","category":"Phòng tranh","cat_key":"gallery","cat_label":"Phòng tranh","description":"Men xanh đồng của gốm Biên Hoà, từ những chiếc chum cũ của Lò Gốm Tân Vạn tới tượng nhỏ của nghệ nhân trẻ Mai Hạ. Triển lãm đặt gốm trên bệ gỗ thấp để bạn nhìn được cả đáy và vết lửa. Trà rót trong chén gốm của chính lò. Có thể đặt mua sau buổi xem. Bệ thấp, nhớ coi chừng chân.","intro":"Men xanh đồng Biên Hoà, từ chum cũ tới tượng nhỏ của nghệ nhân trẻ.\n\nTrà rót trong chén gốm của chính lò.","included":"Vào cửa ▪︎ trà","included_items":[{"label":"Vào cửa","detail":"xem không giới hạn thời gian"},{"label":"trà","detail":"trà nóng trong chén gốm"}],"area":"Quận 1","neighborhood":"Khu phố 6","lat":10.774188,"lng":106.693448,"price_vnd":120000,"price_cents":12000000,"capacity":25,"seats_remaining":25,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/noigiay/DSCF2539.jpg","cover_r2_ref":null,"keywords":["Gốm","Xanh","Biên","Hoà","Quận 1","Phòng tranh","Vào cửa","trà"],"chat_greeting":"Chào bạn! Có câu hỏi về gốm cứ nhắn mình.","chat_greeting_en":"Hi! Ask me anything about the ceramics.","details":{"v":1,"alcohol":"none","min_age":"16","artists":["Lò Gốm Tân Vạn","Mai Hạ"],"medium":["sculpture"]},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
