INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"giayin","key":"giayin","slug":"giayin","organizer_id":"org_a96236c5","name":"In Lụa Một Màu","category":"Phòng tranh","cat_key":"gallery","cat_label":"Phòng tranh","description":"Xưởng In Đèn treo ba mươi bản in lụa chỉ dùng một màu mực, mỗi tấm một sắc độ khác nhau. Giữa phòng là bàn in, bạn tự kéo lụa một tấm A4 để mang về. Vào cửa tự do, giữ chỗ để có khung giờ in. Mặc đồ không ngại dính mực. Mỗi khung giờ in khoảng hai mươi phút, có người hướng dẫn từng bước.","intro":"Ba mươi bản in lụa, chỉ một màu mực.\n\nTự kéo lụa một tấm để mang về, vào cửa tự do.","included":"Vào cửa tự do ▪︎ một bản in","included_items":[{"label":"Vào cửa tự do","detail":"giữ chỗ để có khung giờ in"},{"label":"một bản in","detail":"tự kéo lụa một tấm A4"}],"area":"Quận 3","neighborhood":"Khu phố 9","lat":10.785316,"lng":106.686148,"price_vnd":0,"price_cents":0,"capacity":40,"seats_remaining":40,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/noigiay/DSCF4223.jpg","cover_r2_ref":null,"keywords":["In","Lụa","Một","Màu","Quận 3","Phòng tranh","Vào cửa tự do","một bản in"],"chat_greeting":"Chào bạn! Nhớ mặc đồ không ngại dính mực nhé.","chat_greeting_en":"Hi! Wear clothes you don't mind getting ink on.","details":{"v":1,"alcohol":"none","min_age":"16","artists":["Xưởng In Đèn"],"medium":["print"]},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
