INSERT INTO events SELECT (jsonb_populate_record(NULL::events, to_jsonb(t) || $v23${"id":"chophien","key":"chophien","slug":"chophien","organizer_id":"org_a96236c5","name":"Chợ Phiên Sân Thượng","category":"Pop-up","cat_key":"popup","cat_label":"Pop-up","description":"Một buổi chợ chiều trên sân thượng ở Quận 1 với bốn quầy nhỏ của người làm đồ thủ công. Bếp Nhỏ Sấy bán trái cây sấy, Gốm Mộc mang chén bát men tro, Len Vụn có khăn và túi đan tay, Trà Sớm mời thử trà. Ghé lúc nào cũng được, vào cửa tự do. Mang túi vải nếu bạn định mua nhiều.","intro":"Bốn quầy đồ thủ công trên một sân thượng, vào cửa tự do.\n\nTrái cây sấy, gốm men tro, đồ len đan tay và một chén trà mời.","included":"Vào cửa tự do ▪︎ trà thử","included_items":[{"label":"Vào cửa tự do","detail":"ghé lúc nào cũng được"},{"label":"trà thử","detail":"một chén trà mời ở quầy Trà Sớm"}],"area":"Quận 1","neighborhood":"Khu phố 1","lat":10.771408,"lng":106.698212,"price_vnd":0,"price_cents":0,"capacity":120,"seats_remaining":120,"status":"live","visibility":"public","cancelled_at":null,"cancel_reason":"","reviewed_by":null,"cover_image":"event-photos/compound/DSCF7597.jpg","cover_r2_ref":null,"keywords":["Chợ","Phiên","Sân","Thượng","Quận 1","Pop-up","Vào cửa tự do","trà thử"],"chat_greeting":"Chào bạn! Ghé lúc nào cũng được trong buổi chiều.","chat_greeting_en":"Hi! Drop in any time during the afternoon.","details":{"v":1,"alcohol":"none","min_age":"16","brands":["Bếp Nhỏ Sấy","Gốm Mộc","Len Vụn","Trà Sớm"],"entry_mode":"drop_in","price_range":"budget"},"removed_at":null,"removed_by":null,"removed_from_status":null,"withdrawn_at":null,"resubmission_count":0,"resubmission_window_start":null,"admin_remind_count":0,"last_admin_reminded_at":null,"address_verified":false}$v23$::jsonb || jsonb_build_object(
