INSERT INTO event_photos (event_id, storage_path, sort_order) VALUES ('chophien', 'event-photos/compound/DSCF7597.jpg', 0), ('chophien', 'event-photos/compound/DSCF7584.jpg', 1), ('chophien', 'event-photos/bandai/DSCF4517.jpg', 2);
SELECT e.key, e.cat_key, e.name, to_char(e.starts_at AT TIME ZONE e.tz, 'Dy DD Mon HH24:MI') AS venue_time, e.price_vnd, e.capacity,
       (SELECT count(*) FROM event_photos p WHERE p.event_id = e.id) AS photos,
       (SELECT count(*) FROM events x WHERE x.status = 'live' AND x.visibility = 'public' AND x.cat_key = e.cat_key) AS live_of_type,
       (SELECT count(DISTINCT organizer_id) FROM events x WHERE x.status = 'live' AND x.visibility = 'public' AND x.cat_key = e.cat_key) AS hosts_of_type,
       (SELECT name FROM organizers WHERE id = e.organizer_id) AS host
  FROM events e WHERE e.key IN ('canhchua','bunchay','tranhtoi','dembass','saxsang','vaicu','aodaimoi','maydo','phimcu','gomxanh','giayin','chophien') ORDER BY e.starts_at;
ROLLBACK;
